type Signup = {
    email: string;
    password: string;
    displayName: string;
};
export function validateSignupData(input: Signup): unknown {
    const email = input.email.trim().toLowerCase();
    const displayName = input.displayName.trim();
    const errors: string[] = [];
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))
        errors.push('email');
    if (input.password.length < 8)
        errors.push('password');
    if (displayName.length < 2 || displayName.length > 40)
        errors.push('displayName');
    return errors.length ? { ok: false, errors } : { ok: true, user: { email, displayName } };
}
